DROP TABLE IF EXISTS `vw_cb_merchant_daily_sales`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_cb_merchant_daily_sales`  AS SELECT `o`.`merchant_id` AS `merchant_id`, cast(`o`.`order_time` as date) AS `sales_date`, count(0) AS `total_orders`, sum(case when `o`.`payment_status` = 'paid' then 1 else 0 end) AS `paid_orders`, sum(case when `os`.`status_code` = 'delivered' then 1 else 0 end) AS `delivered_orders`, sum(case when `os`.`status_code` = 'cancelled' then 1 else 0 end) AS `cancelled_orders`, sum(`o`.`total_amount`) AS `gross_order_value`, sum(case when `o`.`payment_status` = 'paid' then `o`.`total_amount` else 0 end) AS `paid_order_value` FROM (`cb_orders` `o` left join `order_status` `os` on(`os`.`status_id` = `o`.`status_id`)) GROUP BY `o`.`merchant_id`, cast(`o`.`order_time` as date) ;

